export{ModalDatoAdicionalArticuloCtrl};function ModalDatoAdicionalArticuloCtrl($scope,$uibModalInstance,params){$scope.articulo=params;let dataEtiqueta=params.etiquetas[0];console.log(params),$scope.etiquetas=dataEtiqueta.etiquetas,$scope.columns=["IMEI","SERIE"],$scope.data=[],$scope.addRow=function(){$scope.data.length!==$scope.articulo.cantidad?$scope.data.push({}):Swal.fire({title:"Datos Adicionales",icon:"warning",html:`El número de datos adicionales proporcionados no debe exceder la cantidad de artículo: <b>${$scope.articulo.descripcion}</b>!`})},$scope.removeRow=function(row){try{let index=$scope.data.indexOf(row);$scope.data.splice(index,1)}catch(error){console.log(error)}},$scope.save=function(){try{if(0===$scope.data.length)return void Swal.fire({title:"Datos Adicionales",icon:"warning",html:"Ingrese los datos adicionales del artículo!"});for(let data of $scope.etiquetas)for(let item of $scope.data)if([null,void 0,""].includes(item[data]))return void Swal.fire({title:"Datos Adicionales",icon:"warning",html:"Ingrese todos campos!"})}catch(error){console.log(error)}},$scope.closeModal=function(){$uibModalInstance.close()}}ModalDatoAdicionalArticuloCtrl.$inject=["$scope","$uibModalInstance","params"];